import{_ as t,o as e,c as i,a5 as r}from"./chunks/framework.a5no_H3L.js";const h=JSON.parse('{"title":"分区数选择","description":"分区数是一个\\"选了就很难改\\"的决策。太少限制并行度，太多增加运维成本。本文给出选型依据和扩展风险。","frontmatter":{},"headers":[],"relativePath":"kafka/04-performance/chapter-03-partition-sizing.md","filePath":"kafka/04-performance/chapter-03-partition-sizing.md"}'),n={name:"kafka/04-performance/chapter-03-partition-sizing.md"};function s(l,a,d,c,p,o){return e(),i("div",null,[...a[0]||(a[0]=[r(`<h1 id="分区数选择" tabindex="-1" data-src-line="1" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md">分区数选择 <a class="header-anchor" href="#分区数选择" aria-label="Permalink to &quot;分区数选择&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><p data-src-line="3" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md">分区数是一个&quot;选了就很难改&quot;的决策。太少限制并行度，太多增加运维成本。本文给出选型依据和扩展风险。</p></blockquote><h2 id="_1-分区数决定了什么" tabindex="-1" data-src-line="5" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md">1. 分区数决定了什么 <a class="header-anchor" href="#_1-分区数决定了什么" aria-label="Permalink to &quot;1. 分区数决定了什么&quot;">​</a></h2><table tabindex="0"><thead data-src-line="7" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><tr data-src-line="7" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><th style="text-align:left;">维度</th><th style="text-align:left;">分区数的影响</th></tr></thead><tbody data-src-line="9" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><tr data-src-line="9" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><td style="text-align:left;">消费并行度</td><td style="text-align:left;">分区数 = 消费并行度的天花板</td></tr><tr data-src-line="10" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><td style="text-align:left;">生产并行度</td><td style="text-align:left;">多分区可以并行写入不同 Broker</td></tr><tr data-src-line="11" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><td style="text-align:left;">故障恢复开销</td><td style="text-align:left;">Broker 故障时需为大量分区重新选举 Leader，分区副本越多控制面开销越大</td></tr><tr data-src-line="12" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><td style="text-align:left;">Controller 压力</td><td style="text-align:left;">元数据管理开销随分区数增长</td></tr><tr data-src-line="13" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><td style="text-align:left;">文件句柄</td><td style="text-align:left;">每个分区对应多个文件</td></tr></tbody></table><h2 id="_2-选型依据" tabindex="-1" data-src-line="15" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md">2. 选型依据 <a class="header-anchor" href="#_2-选型依据" aria-label="Permalink to &quot;2. 选型依据&quot;">​</a></h2><p data-src-line="17" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md">并发数只是分区数的下限之一，不能单独决定分区数。分区数由三个维度共同约束，取其中最大值：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>分区数 ≥ max(写入所需分区数, 消费所需分区数, 消费者并行数)</span></span></code></pre></div><ul data-src-line="23" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><li data-src-line="23" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><strong>写入容量</strong>：目标写入吞吐 ÷ 单分区可持续写入能力。单分区写入能力受消息大小、复制因子、acks 配置影响，不是固定常量。</li><li data-src-line="24" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><strong>消费容量</strong>：目标消费吞吐 ÷ 单分区可持续消费能力，保证分区总数足以承载消费吞吐。</li><li data-src-line="25" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><strong>消费并行度</strong>：需要同时工作的消费者数量，机制见 <a href="./../02-core/chapter-01-partition-and-offset.html">分区与 Offset</a>。</li></ul><p data-src-line="27" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md">消费容量回答「分区能不能装下吞吐」，消费并行度回答「能不能让足够多的消费者同时干活」。两者不等价：多挂一个消费者不必然提高吞吐，还要看分区分配、单分区处理能力和下游瓶颈。</p><p data-src-line="29" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md">三个维度都满足后，最终配置还要结合 Broker 资源上限和实测结果校验。</p><p data-src-line="31" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md">以 KB 级消息、复制因子 3 的典型业务为例，分区数的经验数量级大致是：低吞吐 3~6、中等吞吐 10~30、高吞吐 50~100。这些数字随消息大小和复制因子变化很大，仅用于判断当前分区是否明显偏多或偏少，不能当作容量公式。</p><h2 id="_3-分区过多的代价" tabindex="-1" data-src-line="33" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md">3. 分区过多的代价 <a class="header-anchor" href="#_3-分区过多的代价" aria-label="Permalink to &quot;3. 分区过多的代价&quot;">​</a></h2><p data-src-line="35" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md">分区数量与分区副本总数是两个概念，实际开销取决于副本总数。以下按资源类型区分：</p><table tabindex="0"><thead data-src-line="37" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><tr data-src-line="37" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><th style="text-align:left;">代价</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="39" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><tr data-src-line="39" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><td style="text-align:left;">文件句柄多</td><td style="text-align:left;">每个分区副本对应多个文件（.log, .index, .timeindex）</td></tr><tr data-src-line="40" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><td style="text-align:left;">内存占用增加</td><td style="text-align:left;">每个分区副本的索引和缓冲区消耗内存</td></tr><tr data-src-line="41" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><td style="text-align:left;">复制流量增加</td><td style="text-align:left;">副本总数增加通常会增加副本维护开销和潜在复制负载，实际流量取决于写入速率、消息大小与 ISR 状态</td></tr></tbody></table><p data-src-line="43" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md">故障恢复要区分两个阶段：单个分区的 Leader 选举开销很小；Broker 故障会同时触发大量分区重新选举、元数据更新和副本恢复，恢复时间取决于受影响的分区副本数量与控制面、数据面负载，不存在统一的固定阈值。排查见 <a href="./../05-troubleshooting/chapter-06-broker-failure.html">Broker 故障</a>。</p><blockquote data-src-line="45" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><p data-src-line="45" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md">如果分区副本总数过大导致恢复变慢，先检查是否分区过量、副本数是否需要收敛，而不是简单追加分区。</p></blockquote><h2 id="_4-分区扩展" tabindex="-1" data-src-line="47" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md">4. 分区扩展 <a class="header-anchor" href="#_4-分区扩展" aria-label="Permalink to &quot;4. 分区扩展&quot;">​</a></h2><p data-src-line="49" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md">分区数只能增加、不能减少。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kafka-topics.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --alter</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --topic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-topic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --partitions</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 12</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bootstrap-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost:9092</span></span></code></pre></div><h3 id="扩展风险" tabindex="-1" data-src-line="55" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md">扩展风险 <a class="header-anchor" href="#扩展风险" aria-label="Permalink to &quot;扩展风险&quot;">​</a></h3><table tabindex="0"><thead data-src-line="57" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><tr data-src-line="57" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><th style="text-align:left;">风险</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="59" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><tr data-src-line="59" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><td style="text-align:left;">Key 路由变化</td><td style="text-align:left;">默认哈希分区逻辑下，新增分区改变取模结果，同一 Key 的新消息可能进入不同分区，跨分区无序</td></tr><tr data-src-line="60" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><td style="text-align:left;">消费者 Rebalance</td><td style="text-align:left;">分区数变化触发 Rebalance</td></tr><tr data-src-line="61" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><td style="text-align:left;">数据倾斜</td><td style="text-align:left;">新分区没有历史数据，短期内数据不均衡</td></tr></tbody></table><p data-src-line="63" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md">带 Key 的消息在默认哈希分区逻辑下，按序列化后的 Key 与当前分区数取模决定目标分区；无 Key 的消息走粘性分区，不受取模变化影响。扩容不会迁移历史消息，旧消息留在原分区，同一业务实体的新旧消息因此可能分散到不同分区，即使单分区内部有序，跨分区也没有顺序保证。使用自定义分区器或稳定分片映射时不适用上述结论。</p><h3 id="扩展前的检查清单" tabindex="-1" data-src-line="65" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md">扩展前的检查清单 <a class="header-anchor" href="#扩展前的检查清单" aria-label="Permalink to &quot;扩展前的检查清单&quot;">​</a></h3><ol data-src-line="67" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md"><li data-src-line="67" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md">该 Topic 是否依赖 Key 的顺序性？如果是，扩展分区会破坏顺序</li><li data-src-line="68" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md">消费者组中有多少个消费者？扩展后是否需要增加消费者</li><li data-src-line="69" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md">是否在低峰期执行？扩展会触发 Rebalance，影响消费</li><li data-src-line="70" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md">扩容前先确认瓶颈在分区并行度而非消费者处理速度，判断方法见 <a href="./../05-troubleshooting/chapter-01-consumer-lag.html">消费者 Lag 过大</a></li></ol><h2 id="_5-分区数-vs-消费者数" tabindex="-1" data-src-line="72" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md">5. 分区数 vs 消费者数 <a class="header-anchor" href="#_5-分区数-vs-消费者数" aria-label="Permalink to &quot;5. 分区数 vs 消费者数&quot;">​</a></h2><p data-src-line="74" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md">同一消费者组内，一个分区同一时刻至多分配给一个消费者，但消费者与分区不必一一对应。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>消费者数 &lt; 分区数：每个消费者负责多个分区</span></span>
<span class="line"><span>消费者数 &gt; 分区数：多余的消费者空闲，不参与消费</span></span></code></pre></div><p data-src-line="81" data-src-file="kafka/04-performance/chapter-03-partition-sizing.md">消费者数量由处理能力、分区分配和故障恢复时间要求共同决定，不等于「分区数减一」。需要故障后快速恢复时，应通过实例部署和消费组协调设计冗余，而不是多挂一个消费者当热备——同一组内新增消费者会直接参与分区分配，不会自动处于待命状态。</p>`,28)])])}const k=t(n,[["render",s]]);export{h as __pageData,k as default};
